import { requireVendorContext } from "@/lib/auth/vendor-context";
import { v1Data, v1Exception } from "@/lib/api/v1/response";
import { PaymentEligibilityService } from "@/services/payment-eligibility";
const messages: Record<string, string> = { READY: "Online payments are active.", NO_PAYMENT_ACCOUNT: "Add and verify an MTN or Airtel merchant account before accepting online payments.", PAYMENT_ACCOUNT_PENDING: "Your merchant account is being verified.", PAYMENT_ACCOUNT_REJECTED: "Your merchant payment account needs attention.", PAYMENT_ACCOUNT_SUSPENDED: "Your merchant payment account is temporarily unavailable.", NO_ENABLED_PAYMENT_PROVIDER: "No configured payment provider is currently enabled.", SHOP_INACTIVE: "This shop is not active." };
export async function GET() { try { const context = await requireVendorContext("vendor:manage_legal"); const result = await PaymentEligibilityService.canAcceptPayments(context.vendorId); const status = result.eligible ? "READY" : result.reasons[0] ?? "NO_PAYMENT_ACCOUNT"; return v1Data({ ready: result.eligible, status, message: messages[status] ?? "Online payments are unavailable." }); } catch (error) { return v1Exception(error); } }
